import pandas as pd
import re
from dateutil import parser

file_path = '/data/mixed_units_register.xlsx'
df = pd.read_excel(file_path, sheet_name='Disbursement Register', header=5)

# Clean column names
print(df.columns.tolist())
print(df.shape)

# Helper parse date
def parse_date(val):
    if pd.isna(val):
        return None
    s = str(val).strip()
    # try multiple parsers
    for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%d %b %Y', '%-d %b %Y', '%d %B %Y'):
        try:
            # python's strptime doesn't support %-d on Windows? Try both
            return pd.to_datetime(s, format=fmt, errors='raise')
        except:
            pass
    # fallback to dateutil
    try:
        dt = parser.parse(s, dayfirst=True)
        return pd.Timestamp(dt.date())
    except:
        return None

def parse_amount(val):
    if pd.isna(val):
        return 0
    s = str(val).strip()
    if s.lower() in ('', '-', 'na', 'n/a', 'nan'):
        return 0
    # remove currency symbols, commas
    s_clean = s.replace('₹', '').replace(',', '').strip()
    # match number with optional unit
    # e.g., 1.2 L, 2.5 lakh, 1 Cr, 45k, 340000, ₹1,20,000
    # find numeric part
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([a-zA-Z]+)?$', s_clean)
    if m:
        num = float(m.group(1))
        unit = m.group(2)
        if not unit:
            return int(num)
        unit = unit.lower()
        if unit in ('l', 'lakh'):
            return int(num * 100000)
        if unit == 'cr':
            return int(num * 10000000)
        if unit == 'k':
            return int(num * 1000)
        # handle 'lakh' already
        # if unit starts with 'lakh'
        if 'lakh' in unit:
            return int(num * 100000)
        # unknown
        return int(num)
    # try extract number with commas like 1,20,000
    # if no unit, try parse as float
    try:
        # remove non-digit dot
        num_str = re.sub(r'[^\d\.]', '', s_clean)
        if num_str:
            return int(float(num_str))
    except:
        pass
    return 0

# Apply parsing
df['parsed_date'] = df['Disbursement Date'].apply(parse_date)
df['parsed_amount'] = df['Amount'].apply(parse_amount)

# Filter
mask_prog = df['Programme'] == 'Maternal & Child Health'
mask_date = df['parsed_date'] >= pd.Timestamp('2025-04-01') & df['parsed_date'] <= pd.Timestamp('2025-06-30')
filtered = df[mask_prog & mask_date]

print('Filtered rows:', len(filtered))
print(filtered[['Record ID','Disbursement Date','parsed_date','Amount','parsed_amount']])

total = filtered['parsed_amount'].sum()
print('Total', total)

